                    {% if DetailPage != '' %}
                        <a href = '{{ DetailPage }}?contentItemId={{ item.Id }}' >{{ item.Title }}</a>
                    {% else %}
                        {{ item.Title }}
                    {% endif %}
                    
                    {% case item.Status %}
                        {% when 'PendingApproval' %}
                            <span class='label label-warning'>Pending</span>
                        {% when 'Approved' %}
