First names alone are ok, but pay attention to other details which might make it easy to uniquely identify an individual within a community.
{%- endif %}

```Prayer Request```
{{PrayerRequest.Text}}
```Prayer Request```
Respond with ONLY a VALID JSON object in the format below. Do not use backticks ```.
{
"sentimentId": <The Id of the Sentiment from the list delimited by ```Sentiments``` that most closely matches the main theme of the prayer request text>,
"categoryId": <The Id of the Category from the list delimited by ```Categories``` that most closely matches the main theme of the prayer request text>,
"isAppropriateForPublic": <boolean value indicating whether the prayer request text is appropriate for public viewing>
}
"}

//- Styles

<style>

    @media (max-width: 991px) {
        .course-side-panel {
            padding-left: 0;
        }
        .card {
            margin-bottom: 24px;
        }
    }
    
    @media (max-width: 767px) {
        h1 {
            font-size: 28px;
        }
        .card {
            margin-bottom: 24px;
        }
    }

</style>

{% if CourseInfo.Id == 0 %}
    <div class="alert alert-warning">You are not authorized to view this content.</div>
    {% return %}
{% endif %}

<div class="d-flex flex-column gap-4">
    
    <div class="hero-section">
        <div class="hero-section-image" style="background-image: url('/GetImage.ashx?guid={{ CourseInfo.ImageFileGuid}}')"></div>
        <div class="hero-section-content">
            <h1 class="hero-section-title"> {{ CourseInfo.PublicName }} </h1>
            <p class="hero-section-description"> {{ CourseInfo.Summary }} </p>
        </div>
    </div>

    <div>

        <div class="row">

            <div class="col-xs-12 col-sm-12 col-md-8"> //- LEFT CONTAINER

                <div class="card rounded-lg"> //- COURSE DESCRIPTION

                    <div class="card-body">
                        <div class="card-title">
                            <h4 class="m-0">Course Description</h4>
                        </div>
                        <div class="card-text">
                            {% if CourseInfo.CourseCode != empty %}
                            <div class="text-gray-600 d-flex gap-1">
                                <p class="text-bold mb-0">Course Code: </p>
                                <p class="mb-0">{{CourseInfo.CourseCode}}</p>
                            </div>
                            {% endif %}

                            {% if CourseInfo.Credits != empty and CourseInfo.Credits != 0 %}
                            <div class="d-flex text-gray-600 gap-1 pb-3">
                                <p class="text-bold mb-0">Credits: </p>
                                <p class="mb-0">{{CourseInfo.Credits}}</p>
                            </div>
                            {% endif %}

                            <div class="pt-3 border-top border-gray-200">
                                {% if CourseInfo.DescriptionAsHtml == empty %}
                                    <span>No course description provided.</span>
                                {% else %}
                                    <span>{{CourseInfo.DescriptionAsHtml}}</span>
                                {% endif %}
                            </div>
                        </div>
                    </div>

                </div>

            </div>

            <div class="col-xs-12 col-sm-12 col-md-4"> //- RIGHT CONTAINER
                <div class="card rounded-lg mb-4">
                    <div class="card-body">
                        <div class="card-title d-flex align-items-center">
							<h4 class="m-0"><span><i class="ti ti-clipboard-list mr-2"></i></span>Requirements
							    {% if CourseInfo.UnmetPrerequisites != empty %}
                                    <i class="ti ti-exclamation-circle text-danger"></i>
                                    </h4>
                                {% else %}
                                    <i class="ti ti-circle-check text-success"></i>
                                    </h4>
                                {% endif %}
							</h4>
						</div>
						<div class="card-text text-muted">
							{% if CourseInfo.CourseRequirements != empty %}
                                {% assign requirementsText = CourseInfo.CourseRequirements |
                                Select:'RequiredLearningCourse' | Select:'PublicName' | Join:', ' | ReplaceLast:',',' and' | Default:'None' %}
                                {% if CourseInfo.UnmetPrerequisites != empty %}
                                    </p>
                                    <p class="mb-0">{{requirementsText}}</p>
                                    <p class="text-danger mb-0 mt-3">You do not meet the course requirements.</p>
                                {% else %}
                                    </p>
                                    <p class="mb-0">{{requirementsText}}</p>
                                {% endif %}
                            {% else %}
                            <p class="mb-0">None</p>
                            {% endif %}
						</div>
                    </div>
                </div>
                
                {% assign today = 'Now' | Date:'yyyy-MM-dd' | AsDateTime %}
                {% assign hasClasses = false %}
                {% for semesterInfo in CourseInfo.Semesters %}
                    
                    {% for classInfo in semesterInfo.AvailableClasses %}
                        {% if semesterInfo.EnrollmentCloseDate == null or semesterInfo.EnrollmentCloseDate >= today %}
                            {% assign hasClasses = true %}
						{% endif %}
						//- CURRENTLY ENROLLED
						{% assign isActiveSemester = semesterInfo.StartDate == null 
						    or today >= semesterInfo.StartDate %}
						{% if classInfo.IsEnrolled 
						and classInfo.StudentParticipant.LearningCompletionStatus == "Incomplete" 
						and isActiveSemester %} 
							
							<div class="card rounded-lg mb-4">
								<div class="card-body">
									<div class="card-title d-flex align-items-center">
										<i class="ti ti-user-check mr-2"></i>
										<h4 class="m-0">Currently Enrolled</h4>
									</div>
									<div class="card-text text-muted mb-3">
										<p>You are currently enrolled in this course.</p>
										<p class="text-gray-800"><i class="ti ti-arrow-right mr-2"></i>{{classInfo.Name}}</p>
									</div>
									<div>
										<a class="btn btn-info" href="{{ classInfo.WorkspaceLink }}">View Class Workspace</a>
									</div>
								</div>
							</div>
                        {% elseif classInfo.StudentParticipant and classInfo.StudentParticipant.LearningCompletionStatus != "Incomplete" %}
							
                            //- HISTORICAL ACCESS
                            {% if CourseInfo.AllowHistoricalAccess == true %}
                            
                                <div class="card rounded-lg mb-4">
                                    
                                    <div class="card-body">
                                        <div class="card-title d-flex align-items-center">
                                            <i class="ti ti-arrow-back-up mr-2"></i>
                                            <h4 class="m-0">History</h4>
                                        </div>
                                        <div class="text-muted">You completed this class on {{
                                            classInfo.StudentParticipant.LearningCompletionDateTime | Date: 'sd' }}.</div>

                                        {% if CourseInfo.IsCompletionOnly == false %}
                                        <div class="mt-3">
                                            <div class="text-muted">
                                                <p class="text-bold mb-0">Grade</p>
                                                <p class="mb-0">{{ classInfo.StudentParticipant.LearningGradingSystemScale.Name }}</p>
                                            </div>
                                        </div>
                                        {% endif %}

                                        <div class="mt-2">
                                            <a href="{{ classInfo.WorkspaceLink }}">View Class Workspace</a>
                                        </div>
                                    </div>
                                    
                                </div>
							 
							//- NO HISTORICAL ACCESS
							{% else %}
                                
                                <div class="card rounded-lg mb-4">
                                    
                                    <div class="card-body">
                                        <div class="card-title d-flex align-items-center">
                                            <i class="ti ti-arrow-back-up mr-2"></i>
                                            <h4 class="m-0">History</h4>
                                        </div>
                                        <div class="text-muted">You completed this class on {{
                                            classInfo.StudentParticipant.LearningCompletionDateTime | Date: 'sd' }}</div>

                                        {% if CourseInfo.IsCompletionOnly == false %}
                                        <div class="mt-3">
                                            <div class="text-muted">
                                                <p class="text-bold mb-0">Grade</p>
                                                <p class="mb-0">{{ classInfo.StudentParticipant.LearningGradingSystemScale.Name }}</p>
                                            </div>
                                        </div>
                                        {% endif %}
                                    </div>
                                    
                                </div>
                                
                            {% endif %}
                        {% endif %}
                    {% endfor %}
                {% endfor %}
                                
                {% if hasClasses == false %} //- NO UPCOMING SEMESTERS OR CLASSES
                    <div class="card rounded-lg">
                        <div class="card-body">
                            <h4 class="mt-0">No Available Upcoming Classes</h4>
                            <p class="text-gray-600">Please check back again later.</p>
                        </div>
                    </div>
                {% else %}
                    <div class="card rounded-lg">
                        <div class="card-body">
                            <h4 class="card-title mt-0"><i class="ti ti-chalkboard-teacher mr-2"></i>Classes</h4>
                            
                            //- SCOPING TO CLASS DETAILS
                            
                            {% for semesterInfo in CourseInfo.Semesters %}

                                {% assign semesterStartDate = semesterInfo.StartDate | Date: 'sd' %}
                                {% assign semesterEndDate = semesterInfo.EndDate | Date: 'sd' %}
                                {% if CourseInfo.ProgramInfo.ConfigurationMode == "AcademicCalendar" %}
                                    <div class="py-1">
                                        <h5 class="mt-0 mb-0">{{semesterInfo.Name}}</h5>
                                        {% if semesterStartDate and semesterEndDate %}
                                            <p class="text-gray-600">{{semesterStartDate}}-{{semesterEndDate}}</p>
                                        {% elseif semesterEndDate != empty %}
                                            <p class="text-gray-600">{{semesterStartDate}}</p>
                                        {% else %}
                                            <p class="text-gray-600">Date Pending</p>
                                        {% endif %}
                                    </div>
                                {% endif %}
                                        
                                {% for classInfo in semesterInfo.AvailableClasses %}
                                    {% assign facilitatorsText = classInfo.Facilitators | Select:'Name' | Join:', ' | ReplaceLast:',',' and' | Default:'TBD' %}
                                   
                                    <div class="card rounded-lg bg-gray-100 mb-4">
                                        <div class="card-body pb-0">
                                            <div class="d-grid grid-flow-row gap-0 mb-3"> //- BEGIN CLASS DETAILS
                                                
                                                {% if CourseInfo.ProgramInfo.ConfigurationMode == "AcademicCalendar" %}
                                                    <p class="text-bold">{{classInfo.Name}}
                                                    {% if classInfo.IsEnrolled and classInfo.StudentParticipant.LearningCompletionStatus == "Incomplete" %}
                                                        <span class="text-normal align-top badge bg-info">Enrolled</span>
                                                    {% elseif classInfo.IsEnrolled %}
														<span class="text-normal align-top badge bg-success">Recently Completed</span>
                                                    {% endif %}
                                                    </p>
                                                {% else %}
                                                <h4 class="mt-0">Class Details</h4>
                                                {% endif %}
                                                
                                                <div class="d-flex flex-column">
                                                    {% if facilitatorsText %}
                                                        <div class="text-gray-600">
                                                            <p class="text-bold mb-0">Facilitators: 
                                                            <p>{{facilitatorsText}}</p>
                                                        </div>
                                                    {% endif %}
                                                    
                                                    {% if classInfo.Campus %}
                                                        <div class="text-gray-600">
                                                            <p class="text-bold mb-0">Campus: 
                                                            <p>{{classInfo.Campus}}</p>
                                                        </div>
                                                    {% endif %}
                                                    {% if classInfo.Location and classInfo.Location != '' %}
                                                        <div class="text-gray-600">
                                                            <p class="text-bold mb-0">Location: 
                                                            <p>{{classInfo.Location}}</p>
                                                        </div>
                                                    {% endif %}
                                                    {% if classInfo.Schedule %}
                                                        <div class="text-gray-600">
                                                            <p class="text-bold mb-0">Schedule: 
                                                            <p>{{classInfo.Schedule}}</p>
                                                        </div>
                                                    {% endif %}
                                                    
                                                    {% if classInfo.IsEnrolled  == false %} //- NEVER ENROLLED?
                                                        {% if semesterInfo.IsEnrolled == true and classInfo.IsEnrolled == false %}
                                                            {% if CourseInfo.ProgramInfo.ConfigurationMode == "AcademicCalendar" %}
                                                                <p class="text-danger">You've already enrolled in this course this semester.</p>
                                                            {% else %}
                                                                <p class="text-danger">You've already enrolled in a version of this course.</p>
                                                            {% endif %}
                                                        {% elseif classInfo.CanEnroll == false %}
                                                            {% if classInfo.EnrollmentErrorKey == 'class_full' %}
                                                                <p class="text-danger">Class is full.</p>
                                                            {% endif %}
                                                        
                                                        {% else %}
                                                            {% if CourseInfo.ProgramInfo.ConfigurationMode != "AcademicCalendar" or semesterInfo.IsEnrolled  == false %}
                                                                <div>
                                                                    <a class="btn btn-default" href="{{ classInfo.EnrollmentLink }}">Enroll</a>
                                                                </div>
                                                            {% endif %}
                                                        {% endif %}
                                                    {% endif %}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                {% endfor %}
       
                            {% endfor %}
                        
                        </div>
                    </div>        
                    
                {% endif %}

            </div>
        </div>
    </div>
</div>

{% if CurrentPerson %}
    {{ CurrentPerson.NickName }}, could you please complete the form below.
{% else %}
    Please complete the form below.
{% endif %}
<div class="form-group">
    <label for="firstname">First Name</label>
    {% if CurrentPerson %}
        <p>{{ CurrentPerson.NickName }}</p>
        <input type="hidden" id="firstname" name="FirstName" value="{{ CurrentPerson.NickName }}" />
    {% else %}
        <input type="text" class="form-control" id="firstname" name="FirstName" placeholder="First Name" required />
    {% endif %}
</div>
<div class="form-group">
    <label for="lastname">Last Name</label>
   
    {% if CurrentPerson %}
        <p>{{ CurrentPerson.LastName }}</p>
        <input type="hidden" id="lastname" name="LastName" value="{{ CurrentPerson.LastName }}" />
    {% else %}
        <input type="text" class="form-control" id="lastname" name="LastName" placeholder="Last Name" required />
    {% endif %}
</div>
<div class="form-group">
    <label for="email">Email</label>
    {% if CurrentPerson %}
        <input type="email" class="form-control" id="email" name="Email" value="{{ CurrentPerson.Email }}" placeholder="Email" required />
    {% else %}
        <input type="email" class="form-control" id="email" name="Email" placeholder="Email" required />
    {% endif %}
</div>
<div class="form-group">
    <label for="message">Message</label>
    <textarea id="message" rows="4" class="form-control" name="Message" placeholder="Message" required></textarea>
</div>
<div class="form-group">
    <label for="attachment">Attachment</label>
    <input type="file" id="attachment" name="attachment" /> <br />
    <input type="file" id="attachment2" name="attachment2" />
</div>

{{ 'Global' | Attribute:'EmailHeader' }}
<p>
    A email form has been submitted. Please find the information below:
</p>
{% for field in FormFields %}
    {% assign fieldParts = field | PropertyToKeyValue %}
    <strong>{{ fieldParts.Key | Humanize | Capitalize }}</strong>: {{ fieldParts.Value }} <br/>
{% endfor %}
<p>&nbsp;</p>
{{ 'Global' | Attribute:'EmailFooter' }}

//-Variable Assignments
{% assign facilitatorCount = Facilitators | Size %}
{% assign facilitatorsText = '' %}

{% for f in Facilitators %}
    {%- capture name -%}
        {{f | Property:'Name'}}{%- unless forloop.last -%}, {% endunless %}
    {%- endcapture -%}
    {% assign facilitatorsText = facilitatorsText | Append:name %}
{% endfor %}

{% if facilitatorsText == empty %}
    {% assign facilitatorsText = 'TBD' %}
{% endif %}
{% assign credits = LearningClass.LearningCourse.Credits | AsInteger %}
{% assign location = LearningClass.GroupLocations | First %}
{% assign locationNameLength = location.Name | Size %}
{% assign schedule = LearningClass.Schedule %}
{% assign scheduleNameLength = schedule.Name | Size %}
{% assign hasLocation = locationNameLength > 0 %}
{% assign hasSchedule = scheduleNameLength > 0 %}


{% stylesheet %}
    .confirmation-details {
        width: 100%;
        max-width: 545px;
    }
    
    .detail-table {
        border: 1px solid var(--color-interface-softer);
        width: 100%;
    }
    
    .detail-row {
        border-bottom: 1px solid var(--color-interface-softer);
        padding: 8px;
        width: 100%;
    }
    
    .detail-row:last-child {
        border-bottom: none;
    }

    
{% endstylesheet %}



<div class="d-flex flex-column w-100 justify-content-center gap-4 my-4">
    
    //- 1 REVIEW HEADING
    <div>
        <h3 class="text-center">Enrollment Review</h3>
        <div class="text-center">Please review class details before confirming enrollment:</div>
    </div>
    
    //- 2 TABLE
    <div class="d-flex flex-column mt-3 gap-3">
        <div>
            <h5>Participant Details</h5>
            <div class="detail-table">
                <div class="detail-row d-flex justify-content-between">
                    <div class="field-title">
                        Name
                    </div>
                    <div class="field-value">
                        {{Registrant.FullName}}
                    </div>
                </div>
                <div class="detail-row participant-email d-flex justify-content-between">
                    <div class="field-title">
                        Email
                    </div>
                    <div class="field-value">
                        {{Registrant.Email}}
                    </div>
                </div>
            </div>
        </div>
        
        <div>
            <h5>Class Details</h5>
            <div class="detail-table">
                <div class="detail-row  d-flex justify-content-between">
                    <div class="field-title">
                        Course Name
                    </div>
                    <div class="field-value">
                        {{LearningClass.LearningCourse.PublicName}}
                    </div>
                </div>
                {% if LearningClass.LearningCourse.CourseCode != empty %}
                <div class="detail-row  d-flex justify-content-between">
                    <div class="field-title">
                        Course Code
                    </div>
                    <div class="field-value">
                        {{LearningClass.LearningCourse.CourseCode}}
                    </div>
                </div>
                {% endif %}
        
                <div class="detail-row d-flex justify-content-between">
                    <div class="field-title">
                        Course Configuration
                    </div>
                    <div class="field-value ">
                        {% if LearningClass.LearningCourse.LearningProgram.ConfigurationMode == 0 %}
                            Academic Calendar
                        {% elseif LearningClass.LearningCourse.LearningProgram.ConfigurationMode == 1 %}
                            On-Demand
                        {% endif %}
                    </div>
                </div>
        
                <div class="detail-row d-flex justify-content-between">
                    <div class="field-title">
                        {{ 'Facilitator' | PluralizeForQuantity:facilitatorCount }}:
                    </div>
                    <div class="field-value">
                        {{facilitatorsText}}
                    </div>
                </div>
        
                {% if credits > 0 %}
                    <div class="detail-row d-flex justify-content-between">
                        <div class="field-title">
                            Credits
                        </div>
                        <div class="field-value">
                            {{LearningClass.LearningCourse.Credits}}
                        </div>
                    </div>
                {% endif %}
        
                <div class="detail-row d-flex justify-content-between">
                    <div class="field-title">
                        Grading System
                    </div>
                    <div class="field-value">
                        {{LearningClass.LearningGradingSystem.Name}}
                    </div>
                </div>
        
                <div class="detail-row d-flex justify-content-between">
                    <div class="field-title">
                        Semester
                    </div>
                    <div class="field-value">
                        {{LearningClass.LearningSemester.Name}}
                    </div>
                </div>
        
                {% if hasLocation %}
                    <div class="detail-row d-flex justify-content-between">
                        <div class="field-title">
                            Location
                        </div>
                        <div class="field-value">
                            {{location.Name}}
                        </div>
                    </div>
                {% endif %}
        
                {% if hasSchedule %}
                    <div class="detail-row d-flex justify-content-between">
                        <div class="field-title">
                            Schedule
                        </div>
                        <div class="field-value">
                            {{schedule.Name}}
                        </div>
                    </div>
                {% endif %}
        
                {% if LearningClass.LearningSemester.StartDate %}
                    <div class="detail-row d-flex justify-content-between">
                        <div class="field-title">
                            Starts
                        </div>
                        <div class="field-value">
                            {{LearningClass.LearningSemester.StartDate |  Date:'sd' }}
                        </div>
                    </div>
                {% endif %}
            </div>
        </div>
    </div>

</div>
